mapper.update:
UPDATE NOTES
   SET DELETED_YN='Y',UPD_DT=SYSDATE,UPDATED_BY=#{userId}
 WHERE NOTE_ID=(SELECT CONTENT_ID FROM CONTENT_RECORD_ITEMS WHERE RECORD_TARGET_ID=#{recordTargetId} AND RECORD_ITEM_ID=#{recordItemId} AND RECORD_TYPE='NOTE' AND DELETED_YN='N')

UPDATE CONTENT_RECORD_ITEMS
   SET SORT_ORDER=#{sortOrder},UPDATED_AT=SYSDATE
 WHERE RECORD_TARGET_ID=#{recordTargetId}
   AND RECORD_ITEM_ID=#{recordItemId}
   AND RECORD_TYPE='NOTE'
   AND DELETED_YN='N'

UPDATE CONTENT_RECORD_LINKS l
   SET l.LINK_URL=#{linkUrl},l.LINK_TITLE=#{title,jdbcType=VARCHAR},l.DESCRIPTION=#{description,jdbcType=VARCHAR}
 WHERE l.RECORD_ITEM_ID=#{recordItemId}
   AND EXISTS (SELECT 1 FROM CONTENT_RECORD_ITEMS i WHERE i.RECORD_ITEM_ID=l.RECORD_ITEM_ID AND i.RECORD_TARGET_ID=#{recordTargetId} AND i.RECORD_TYPE='LINK' AND i.DELETED_YN='N')

UPDATE CONTENT_RECORD_LOCATIONS p SET p.PRIMARY_YN='Y'
 WHERE p.RECORD_ITEM_ID=#{recordItemId}
   AND EXISTS (SELECT 1 FROM CONTENT_RECORD_ITEMS i WHERE i.RECORD_ITEM_ID=p.RECORD_ITEM_ID AND i.RECORD_TARGET_ID=#{recordTargetId} AND i.RECORD_TYPE='LOCATION' AND i.DELETED_YN='N')

UPDATE CONTENT_RECORD_ITEMS i
   SET i.UPDATED_AT=SYSDATE
 WHERE i.RECORD_TYPE=#{recordType}
   AND i.CONTENT_ID=#{contentId}
   AND NVL(i.DELETED_YN,'N')='N'
   AND EXISTS (
       SELECT 1 FROM CONTENT_RECORD_TARGETS t
        WHERE t.RECORD_TARGET_ID=i.RECORD_TARGET_ID
          AND NVL(t.TARGET_STATUS,'ACTIVE')='ACTIVE'
   )

UPDATE CONTENT_RECORD_ITEMS
   SET DELETED_YN=#{deletedYn}, UPDATED_AT=SYSTIMESTAMP
 WHERE RECORD_TYPE=#{recordType}
   AND CONTENT_ID=#{contentId}

mapper.delete:
DELETE FROM CONTENT_RECORD_ITEMS
 WHERE RECORD_TYPE=#{recordType}
   AND CONTENT_ID=#{contentId}
